7	#define MAX_ARGS 8
8	
9	static int parse_expr(struct lexer *lx, int min_prec, double *out);
10	
11	static const struct token *peek(const struct lexer *lx)
12	{
13	    return &lx->toks[lx->pos];
14	}
15	
16	static int syntax_error(const struct token *t)
17	{
18	    qs_set_error("syntax error at column %zu", t->col);
19	    return -1;
20	}
21	
22	static int parse_call(struct lexer *lx, const struct token *name, double *out)
23	{
24	    const struct qs_op *op = qs_op_find(name->text, 1);
25	    if (!op) {
26	        qs_set_error("unknown function '%s'", name->text);
27	        return -1;
28	    }
29	    if (peek(lx)->kind != TOK_LPAREN)
30	        return syntax_error(peek(lx));
31	    lx->pos++;
32	
33	    double args[MAX_ARGS];
34	    int n = 0;
35	    if (peek(lx)->kind != TOK_RPAREN) {
36	        for (;;) {
37	            double v;
38	            if (parse_expr(lx, 0, &v))
39	                return -1;
40	            if (n < MAX_ARGS)
41	                args[n] = v;
42	            n++;
43	            if (peek(lx)->kind != TOK_COMMA)
44	                break;
45	            lx->pos++;
46	        }
47	    }
48	    if (peek(lx)->kind != TOK_RPAREN)
49	        return syntax_error(peek(lx));
50	    lx->pos++;
51	    if (n != op->arity) {
52	        qs_set_error("'%s' takes %d argument%s", op->token, op->arity, op->arity == 1 ? "" : "s");
53	        return -1;
54	    }
55	    return qs_apply(op, args, out);
56	}
57	
58	static int parse_primary(struct lexer *lx, double *out)
59	{
60	    const struct token *t = peek(lx);
61	    switch (t->kind) {
62	    case TOK_NUM:
63	        lx->pos++;
64	        *out = t->num;
65	        return 0;
66	    case TOK_IDENT:
67	        lx->pos++;
68	        return parse_call(lx, t, out);
69	    case TOK_LPAREN:
70	        lx->pos++;
71	        if (parse_expr(lx, 0, out))
72	            return -1;
73	        if (peek(lx)->kind != TOK_RPAREN)
74	            return syntax_error(peek(lx));
75	        lx->pos++;
76	        return 0;
77	    case TOK_OP:
78	    case TOK_RPAREN:
79	    case TOK_COMMA:
80	        return syntax_error(t);
81	    }
82	    return syntax_error(t);
83	}
84	
85	static int parse_unary(struct lexer *lx, double *out)
86	{
87	    const struct token *t = peek(lx);
88	    if (t->kind == TOK_OP && t->text[0] == '-') {
89	        const struct qs_op *neg = qs_op_named("neg");
90	        double v;
91	        lx->pos++;
92	        if (parse_expr(lx, neg->prec, &v))
93	            return -1;
94	        return qs_apply(neg, &v, out);
95	    }
96	    return parse_primary(lx, out);
97	}
98	
99	/* Precedence climbing: operators below min_prec end the current operand. */
100	static int parse_expr(struct lexer *lx, int min_prec, double *out)
101	{
102	    double lhs;
103	    if (parse_unary(lx, &lhs))
104	        return -1;
105	    for (;;) {
106	        const struct token *t = peek(lx);
107	        if (t->kind != TOK_OP)
108	            break;
109	        const struct qs_op *op = qs_op_find(t->text, 0);
110	        if (!op)
111	            return syntax_error(t);
112	        if (op->prec < min_prec)
113	            break;
114	        lx->pos++;
115	        double rhs;
116	        int next = op->assoc == QS_RIGHT ? op->prec : op->prec + 1;
117	        if (parse_expr(lx, next, &rhs))
118	            return -1;
119	        double args[2] = { lhs, rhs };
120	        if (qs_apply(op, args, &lhs))
121	            return -1;
122	    }
123	    *out = lhs;
124	    return 0;
125	}
126	
127	int qs_parse(struct lexer *lx, double *out)
128	{
129	    if (parse_expr(lx, 0, out))
130	        return -1;
131	    if (peek(lx)->kind != TOK_END)
132	        return syntax_error(peek(lx));
133	    return 0;
134	}
