static struct token *push(struct lexer *lx, enum tok_kind kind, size_t col)
{
    if (lx->count == lx->cap) {
        lx->cap = lx->cap ? lx->cap * 2 : 16;
        lx->toks = qs_xrealloc(lx->toks, lx->cap * sizeof *lx->toks);
