6	
7	static int usage(void)
8	{
9	    fprintf(stderr, "usage: colstat [-d DELIM] [-c COLS] [--max-size N] [--version] [FILE]
");
10	    return COLSTAT_USAGE;
11	}
12	
13	int colstat_parse_args(int argc, char **argv, struct colstat_opts *opts)
14	{
15	    memset(opts, 0, sizeof *opts);
16	    opts->delim = ',';
17	    for (int i = 1; i < argc; i++) {
18	        const char *a = argv[i];
19	        if (strcmp(a, "--version") == 0) {
20	            opts->show_version = 1;
21	        } else if (strcmp(a, "-d") == 0) {
22	            if (++i == argc)
23	                return usage();
24	            if (strcmp(argv[i], "tab") == 0)
25	                opts->delim = '	';
26	            else if (strlen(argv[i]) == 1)
27	                opts->delim = argv[i][0];
28	            else {
29	                fprintf(stderr, "colstat: delimiter must be one character or 'tab'
");
30	                return COLSTAT_USAGE;
31	            }
32	        } else if (strcmp(a, "-c") == 0) {
33	            if (++i == argc)
34	                return usage();
35	            opts->cols = argv[i];
36	        } else if (strcmp(a, "--max-size") == 0) {
37	            if (++i == argc)
38	                return usage();
39	            if (!qs_parse_size(argv[i], &opts->max_size)) {
40	                fprintf(stderr, "colstat: invalid size '%s'
", argv[i]);
41	                return COLSTAT_USAGE;
42	            }
43	            opts->has_max_size = 1;
44	        } else if (a[0] == '-' && a[1] != '\0') {
45	            fprintf(stderr, "colstat: unknown option '%s'
", a);
46	            return usage();
47	        } else if (opts->path) {
48	            return usage();
49	        } else {
50	            opts->path = a;
51	        }
52	    }
53	    return COLSTAT_OK;
54	}
55	
56	int colstat_select(const struct qs_header *h, const char *cols, int **sel, size_t *nsel)
57	{
58	    *nsel = 0;
59	    if (!cols) {
60	        *sel = qs_xmalloc((h->count ? h->count : 1) * sizeof **sel);
61	        for (size_t i = 0; i < h->count; i++)
62	            (*sel)[(*nsel)++] = (int)i;
63	        return COLSTAT_OK;
64	    }
65	
66	    size_t max = 1;
67	    for (const char *p = cols; *p; p++)
68	        if (*p == ',')
69	            max++;
70	    *sel = qs_xmalloc(max * sizeof **sel);
71	
72	    const char *p = cols;
73	    for (;;) {
74	        const char *end = strchr(p, ',');
75	        size_t len = end ? (size_t)(end - p) : strlen(p);
76	        char *name = qs_xstrndup(p, len);
